public class JacksonAnnotationIntrospector_findInjectableValueId_TriageGen0Test {

    private JacksonAnnotationIntrospector introspector;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }

    /**
     * Test case: Annotation is null.
     * Expected: returns null.
     */
    @Test
    public void testFindInjectableValueId_NoAnnotation() {
        AnnotatedMember m = Mockito.mock(AnnotatedMember.class);
        // Since _findAnnotation is protected and internal, we rely on the fact that 
        // if no annotation is found, it returns null. 
        // In a real Jackson environment, this would be handled by the introspector scanning.
        // For unit testing this specific logic, we assume the mock doesn't trigger the annotation find.

        // We need to mock the behavior of _findAnnotation. 
        // However, _findAnnotation is protected. Since we are in the same package, we can't easily 
        // mock the internal call unless we subclass or use PowerMock. 
        // But we can provide a subclass to control the return of _findAnnotation.

        JacksonAnnotationIntrospector spyIntrospector = new JacksonAnnotationIntrospector() {
            @Override
            protected Annotation _findAnnotation(AnnotatedMember m, Class<? extends Annotation> annotationType) {
                return null;
            }
        };

        assertNull(spyIntrospector.findInjectableValueId(m));
    }

    /**
     * Test case: Annotation is present with a non-empty value.
     * Expected: returns the string id.
     */
    @Test
    public void testFindInjectableValueId_WithId() {
        AnnotatedMember m = Mockito.mock(AnnotatedMember.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("myId");

        JacksonAnnotationIntrospector spyIntrospector = new JacksonAnnotationIntrospector() {
            @Override
            protected Annotation _findAnnotation(AnnotatedMember m, Class<? extends Annotation> annotationType) {
                return ann;
            }
        };

        assertEquals("myId", spyIntroslector.findInjectableValueId(m));
    }

    /**
     * Test case: Annotation has empty string value, member is NOT an AnnotatedMethod (e.g., AnnotatedField).
     * Expected: returns m.getRawType().getName().
     */
    @Test
    public void testFindInjectableValueId_EmptyId_Field() {
        AnnotatedMember m = Mockito.mock(AnnotatedMember.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("");
        when(m.getRawType()).thenReturn(String.class);

        JacksonAnnotationIntrospector spyIntrospector = new JacksonAnnotationIntrospector() {
            @Override
            protected Annotation _findAnnotation(AnnotatedMember m, Class<? extends Annotation> annotationType) {
                return ann;
            }
        };

        assertEquals(String.class.getName(), spyIntrospector.findInjectableValueId(m));
    }

    /**
     * Test case: Annotation has empty string value, member is an AnnotatedMethod with 0 parameters.
     * Expected: returns m.getRawType().getName().
     */
    @Test
    public void testFindInjectableValueId_EmptyId_MethodNoParams() {
        AnnotatedMethod am = Mockito.mock(AnnotatedMethod.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("");
        when(am.getParameterCount()).thenReturn(0);
        when(am.getRawType()).thenReturn(Integer.class);

        JacksonAnnotationIntrospector spyIntrospector = new JacksonAnnotationIntrospector() {
            @Override
            protected Annotation _findAnnotation(AnnotatedMember m, Class<? extends Annotation> annotationType) {
                return ann;
            }
        };

        assertEquals(Integer.class.getName(), spyIntrospector.findInjectableValueId(am));
    }

    /**
     * Test case: Annotation has empty string value, member is an AnnotatedMethod with parameters.
     * Expected: returns the name of the first parameter type.
     */
    @Test
    public void testFindInjectableValueId_EmptyId_MethodWithParams() {
        AnnotatedMethod am = Mockito.mock(AnnotatedMethod.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("");
        when(am.getParameterCount()).thenReturn(1);
        when(am.getRawParameterType(0)).thenReturn(Double.class);

        JacksonAnnotationIntrospector spyIntrospector = new JacksonAnnotationIntrospector() {
            @Override
            protected Annotation _findAnnotation(AnnotatedMember m, Class<? extends Annotation> annotationType) {
                return ann;
            }
        };

        assertEquals(Double.class.getName(), spyIntrospector.findInjectableValueId(am));
    }
}
